#include "../include/px4_comm_types.hpp"
#include <Eigen/Dense>
#include <gtest/gtest.h>

using namespace px4_comm_types;

// 快速基础功能测试
class Px4CommTypesQuickTest : public ::testing::Test {
protected:
  void SetUp() override {
    test_time = rclcpp::Time(123, 456);
    test_translation = Eigen::Vector3d(1.0, 2.0, 3.0);
    test_quaternion = Eigen::Quaterniond::Identity();
  }

  rclcpp::Time test_time;
  Eigen::Vector3d test_translation;
  Eigen::Quaterniond test_quaternion;
};

// 测试基础构造和属性
TEST_F(Px4CommTypesQuickTest, BasicConstruction) {
  // 默认构造
  PositionENU default_pos;
  EXPECT_FALSE(default_pos.valid);

  // 参数构造
  PositionENU valid_pos(test_translation, test_quaternion, test_time);
  EXPECT_TRUE(valid_pos.valid);
  EXPECT_EQ(valid_pos.translation, test_translation);
  EXPECT_EQ(valid_pos.timestamp, test_time);
}

// 测试坐标系转换的基本正确性
TEST_F(Px4CommTypesQuickTest, CoordinateConversion) {
  PositionENU pos_enu(test_translation, test_quaternion, test_time);

  // ENU -> NED
  PositionNED pos_ned = enuToNed(pos_enu);
  EXPECT_TRUE(pos_ned.valid);
  EXPECT_EQ(pos_ned.timestamp, test_time);

  // NED -> ENU
  PositionENU pos_enu_back = nedToEnu(pos_ned);
  EXPECT_TRUE(pos_enu_back.valid);

  // 验证双向转换的一致性
  EXPECT_TRUE(pos_enu_back.translation.isApprox(test_translation, 1e-10));
}

// 测试转换矩阵的数学性质
TEST_F(Px4CommTypesQuickTest, TransformationMatrixProperties) {
  // 正交矩阵性质
  Eigen::Matrix3d I = R_ned_from_enu * R_ned_from_enu.transpose();
  EXPECT_TRUE(I.isApprox(Eigen::Matrix3d::Identity(), 1e-10));

  // 行列式为1（保持右手坐标系）
  EXPECT_NEAR(R_ned_from_enu.determinant(), 1.0, 1e-10);
}

// 测试特殊坐标轴转换
TEST_F(Px4CommTypesQuickTest, AxisConversion) {
  // ENU坐标系: X=东, Y=北, Z=上
  // NED坐标系: X=北, Y=东, Z=下

  // 测试东向量 (1,0,0) ENU -> (0,1,0) NED
  PositionENU east_enu(Eigen::Vector3d::UnitX(), test_quaternion, test_time);
  PositionNED east_ned = enuToNed(east_enu);
  EXPECT_TRUE(east_ned.translation.isApprox(Eigen::Vector3d::UnitY(), 1e-10));

  // 测试北向量 (0,1,0) ENU -> (1,0,0) NED
  PositionENU north_enu(Eigen::Vector3d::UnitY(), test_quaternion, test_time);
  PositionNED north_ned = enuToNed(north_enu);
  EXPECT_TRUE(north_ned.translation.isApprox(Eigen::Vector3d::UnitX(), 1e-10));

  // 测试上向量 (0,0,1) ENU -> (0,0,-1) NED
  PositionENU up_enu(Eigen::Vector3d::UnitZ(), test_quaternion, test_time);
  PositionNED up_ned = enuToNed(up_enu);
  EXPECT_TRUE(up_ned.translation.isApprox(-Eigen::Vector3d::UnitZ(), 1e-10));
}

// 测试无效位置处理
TEST_F(Px4CommTypesQuickTest, InvalidPositionHandling) {
  PositionENU invalid_enu; // 默认无效
  PositionNED result_ned = enuToNed(invalid_enu);
  EXPECT_FALSE(result_ned.valid);

  PositionNED invalid_ned; // 默认无效
  PositionENU result_enu = nedToEnu(invalid_ned);
  EXPECT_FALSE(result_enu.valid);
}

// 测试toString功能（基础测试）
TEST_F(Px4CommTypesQuickTest, ToStringBasic) {
  PositionENU pos(test_translation, test_quaternion, test_time);
  std::string str = pos.toString();

  // 检查关键信息是否存在
  EXPECT_FALSE(str.empty());
  EXPECT_TRUE(str.find("Position") != std::string::npos);
  EXPECT_TRUE(str.find("valid=1") != std::string::npos);
}

int main(int argc, char **argv) {
  ::testing::InitGoogleTest(&argc, argv);
  return RUN_ALL_TESTS();
}
